<script setup>
import { computed,onMounted,ref } from 'vue'; import { supabase } from '../lib/supabase'; import { getProducts,getSuppliers } from '../services/data'
const products=ref([]),suppliers=ref([]),editing=ref(null),loading=ref(true),saving=ref(false),error=ref(''),message=ref(''),search=ref('');const empty=()=>({name:'',category:'',unit:'kos',supplier_id:'',lead_time_days:null,safety_stock_days:1,active:true,sort_order:0});const visible=computed(()=>products.value.filter(p=>p.name.toLocaleLowerCase().includes(search.value.toLocaleLowerCase())))
const date=v=>v?new Date(v).toLocaleDateString('sl-SI'):'—'; const qty=p=>p.lastQuantity===null||p.lastQuantity===undefined?'—':Number(p.lastQuantity).toLocaleString('sl-SI',{maximumFractionDigits:1})
async function load(){loading.value=true;try{const [all,supplierList,latest]=await Promise.all([getProducts(),getSuppliers(),supabase.from('inventory_counts').select('id,completed_at').eq('status','completed').order('completed_at',{ascending:false}).limit(1)]);if(latest.error)throw latest.error;let rows=[];if(latest.data?.[0]){const r=await supabase.from('inventory_count_items').select('product_id,quantity').eq('inventory_count_id',latest.data[0].id);if(r.error)throw r.error;rows=r.data}products.value=all.map(p=>({...p,lastQuantity:rows.find(i=>i.product_id===p.id)?.quantity,lastCountedAt:latest.data?.[0]?.completed_at}));suppliers.value=supplierList}catch{error.value='Izdelkov ni bilo mogoče naložiti.'}finally{loading.value=false}}onMounted(load)
function edit(p){editing.value=p?{...p}:empty();message.value=''}async function save(){saving.value=true;error.value='';try{const payload={...editing.value,supplier_id:editing.value.supplier_id||null,lead_time_days:editing.value.lead_time_days===''?null:editing.value.lead_time_days};const {error:e}=payload.id?await supabase.from('products').update(payload).eq('id',payload.id):await supabase.from('products').insert(payload);if(e)throw e;editing.value=null;message.value='Izdelek je shranjen.';await load()}catch{error.value='Izdelka ni bilo mogoče shraniti.'}finally{saving.value=false}}
</script>
<template><section class="page products-page"><header class="products-header"><div><p class="eyebrow">ADMINISTRACIJA</p><h1>Izdelki</h1><p class="muted">{{products.length}} artiklov v katalogu</p></div><button class="add-product" @click="edit()"><span>＋</span> Dodaj</button></header><div class="product-search"><span>⌕</span><input v-model="search" type="search" placeholder="Poišči izdelek" aria-label="Poišči izdelek" /></div><p v-if="error" class="error">{{error}}</p><p v-if="message" class="success">{{message}}</p><form v-if="editing" class="product-form" @submit.prevent="save"><div class="form-heading"><div><p class="eyebrow">{{editing.id?'UREJANJE':'NOV ARTIKEL'}}</p><h2>{{editing.id?editing.name:'Dodaj izdelek'}}</h2></div><button type="button" class="icon-close" @click="editing=null">×</button></div><label>Ime<input v-model="editing.name" required /></label><div class="two-fields"><label>Kategorija<input v-model="editing.category" required /></label><label>Enota<select v-model="editing.unit"><option>kos</option><option>kg</option><option>l</option><option>paket</option><option>škatla</option><option>posoda</option><option>vreča</option><option>rola</option></select></label></div><label>Dobavitelj<select v-model="editing.supplier_id"><option value="">Brez dobavitelja</option><option v-for="s in suppliers" :key="s.id" :value="s.id">{{s.name}}</option></select></label><div class="two-fields"><label>Dobavni rok (dni)<input v-model="editing.lead_time_days" type="number" min="0" placeholder="Privzeto" /></label><label>Varnostna zaloga<input v-model="editing.safety_stock_days" type="number" min="0" required /></label></div><label class="switch-line"><input v-model="editing.active" type="checkbox" /><span>Artikel je aktiven</span></label><div class="form-actions"><button class="secondary" type="button" @click="editing=null">Prekliči</button><button :disabled="saving">{{saving?'Shranjujem …':'Shrani izdelek'}}</button></div></form><div v-if="loading" class="center-state">Nalagam izdelke …</div><div v-else-if="!visible.length" class="empty-products">Ni izdelkov za ta iskani pojem.</div><div v-else class="product-grid"><button v-for="p in visible" :key="p.id" class="product-card" @click="edit(p)"><div class="product-card-top"><span class="category-pill">{{p.category}}</span><span class="active-dot" :class="{off:!p.active}">{{p.active?'Aktiven':'Neaktiven'}}</span></div><strong>{{p.name}}</strong><div class="stock-number">{{qty(p)}} <small>{{p.unit}}</small></div><div class="product-meta"><span>Popis: {{date(p.lastCountedAt)}}</span><span>Uredi ›</span></div></button></div></section></template>
